package com.pulsefit.authservice.controller;
import com.pulsefit.authservice.repo.UserRepository; import com.pulsefit.authservice.service.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public record LoginRequest(@NotBlank String username,@NotBlank String password){} public record LoginResponse(String token,String type,String username,String role){ }
@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest req){var u=users.findByUsername(req.username()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password")); if(!encoder.matches(req.password(),u.getPassword())) throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password"); return new LoginResponse(jwt.generate(u.getUsername(),u.getRole()),"Bearer",u.getUsername(),u.getRole());}
@GetMapping("/validate") public MapResponse validate(@RequestHeader(value="Authorization",required=false) String h){if(h==null||!h.startsWith("Bearer ")||!jwt.valid(h.substring(7)))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid token");return new MapResponse("VALID");} public record MapResponse(String status){} }
